insert into content_bank_shared (title, content, source_type, tags) values
('DẤU HIỆU MỘT GIA ĐÌNH ĐANG CÓ PHÚC KHÍ',
 'Chỉ khi gia đình bạn bắt đầu bước vào giai đoạn hưng vượng, bạn mới có duyên gặp được video này. Đã gặp rồi, xin chúc cả nhà an khang, vạn sự hanh thông.

Nhiều người ngoài kia luôn niềm nở, khách sáo với người dưng nhưng lại trút hết những bực dọc, cáu bẩn lên những người thân thiết nhất. Thực ra đó là một sự mê muội đang âm thầm bào mòn phúc khí của chính gia đình bạn.

Người thân là nhân duyên, là điểm tựa mà bạn phải tu tập từ muôn kiếp mới có được. Hiếu thảo với cha mẹ chính là bồi đắp gốc rễ đức hạnh. Thiện đãi bạn đời chính là bảo vệ phong thủy tốt nhất cho mái ấm.

Một gia đình dù cơm rau đạm bạc nhưng nếu đồng tâm hiệp lực cùng nhìn về một hướng thì chẳng có khó khăn nào là không thể vượt qua. Ngược lại, nếu trong nhà quanh năm cãi vã, gà bay chó nhảy thì phúc khí dẫu lớn đến đâu cũng tan biến. Tài lộc dẫu nhiều đến mấy cũng chẳng thể giữ chân.

Nhà là nơi để nuôi dưỡng tinh thần, sưởi ấm con tim và tụ tài tích phúc, chứ không phải nơi để trút giận hay so đo hơn kém. Với người thân, thêm một phần bao dung, bớt một phần tính toán, phúc đức tự khắc sẽ ngày càng sâu dày.

Cầu tài bên ngoài không bằng cầu hòa bên trong. Tâm thuận thì khí mới thuận. Khí thuận thì nhà mới hưng. Nhà hưng thì tài vận tự nhiên sẽ thông suốt.

Nhưng để giữ được sự hòa thuận ấy, mỗi người trong gia đình đều cần học cách nhìn lại chính mình, học cách sửa mình trước khi trách người. Bởi nhiều khi điều làm tổn hao phúc khí không phải hoàn cảnh bên ngoài, mà là những suy nghĩ lệch lạc và cảm xúc không được soi sáng từ bên trong.

Nếu bạn mong gia đình mình thuận hòa hơn, phúc khí sâu dày hơn, hãy bắt đầu bằng việc quay về sửa chính mình. 21 ngày Giải Nghiệp là hành trình giúp bạn soi lại những tổn thương, oán trách, cố chấp bên trong để học cách sống bao dung, sáng suốt và nhẹ lòng hơn.

Muốn nhà hưng, trước hết tâm mình phải sáng. Ai cần hành trình này, nhắn mình chữ "21 NGÀY".

Chúc cho mái ấm của bạn luôn ngập tràn yêu thương và thịnh vượng.',
 'bai_mau', array['tam_linh','gia_dinh','phuoc_khi']),
('7 DẤU HIỆU PHÚC CỦA BẠN ĐANG RẤT DÀY',
 'Dấu hiệu thứ 7 là điều rất nhiều người từng gặp. Nhưng đa số lại nghĩ đó là xui xẻo. Trong khi nhiều khi... đó lại chính là một lớp bảo vệ rất kín của Phúc.

1. DUNG MẠO THƯỜNG TRẺ HƠN TUỔI — Dung mạo trẻ không chỉ đến từ chăm sóc. Trong tướng học, thần sắc phản ánh tâm thế bên trong. Người giữ tâm an nhiên, sống thiện niệm lâu ngày thường giữ được khí sắc sáng và mềm rất tự nhiên. Đó là dấu hiệu của phúc khí tích trong thần sắc.

2. NGOÀI ĐỜI RẤT CÓ DUYÊN, NHƯNG LÊN HÌNH THÌ KHÔNG ĂN ẢNH — Vì cái duyên của họ không nằm ở đường nét, mà nằm ở thần khí. Khi gặp trực tiếp, ánh mắt, nụ cười và khí chất tạo ra một cảm giác rất dễ chịu. Nhưng máy ảnh chỉ ghi lại hình dáng tĩnh, nên thần khí và phúc khí khó thể hiện trọn vẹn trong khung hình.

3. TRẺ CON, ĐỘNG VẬT NHỎ THƯỜNG THÍCH LẠI GẦN — Trẻ nhỏ và động vật rất nhạy với trường năng lượng hiền hòa. Khi một người mang khí chất ổn định và ấm áp, chúng thường tự nhiên lại gần và quý mến.

4. ĐÔI KHI CHẤP NHẬN CHỊU THIỆT 1 CHÚT — Người phúc dày thường không quá nặng tâm hơn thua. Họ hiểu rằng giữ tâm thiện và sự rộng lượng quan trọng hơn việc giành phần lợi nhỏ. Chính tâm thế đó khiến phúc khí được giữ lại và nhân duyên ngày càng rộng.

5. ĐI ĐẾN ĐÂU CŨNG DỄ ĐƯỢC CHÀO ĐÓN — Có những người bước vào một nơi tự nhiên được đón nhận rất nhẹ nhàng. Không cần cố gắng tạo ấn tượng, nhưng người khác vẫn cảm thấy thoải mái khi ở gần họ. Đó thường là biểu hiện của phúc khí hài hòa, khiến người khác dễ mở lòng.

6. NHÂN DUYÊN TƯƠNG TRỢ KHÁ MẠNH — Trong những thời điểm quan trọng thường xuất hiện người giúp một tay hoặc mở ra một hướng đi. Trong nhân quả học, đó được gọi là quý nhân duyên — kết quả của những thiện duyên đã tích lũy.

7. THƯỜNG GẶP NẠN NHỎ ĐỂ TRÁNH NẠN LỚN — Đôi khi một việc không diễn ra như dự tính. Một chuyến đi bị lỡ, một kế hoạch thay đổi. Lúc đó dễ nghĩ là không may. Nhưng trong nhân quả học, đó thường là cách phúc giúp mình tránh khỏi một biến cố lớn hơn. Người xưa gọi hiện tượng này là nạn nhỏ hóa giải nạn lớn.

Trong 7 dấu hiệu này, bạn thấy mình có dấu hiệu nào rõ nhất?',
 'bai_mau', array['tam_linh','phuoc_khi','listicle']),
('TỐT NGHIỆP TRƯỜNG ĐỜI — 10 ĐIỀU BẠN CẦN THỰC SỰ HIỂU',
 'Một khi bạn hiểu được:

Tích lũy tiền là đổi vận
Ngủ sớm là sống thọ
Đọc sách là khai ngộ
Tự kỷ luật là phá khổ
Nâng nhận thức là mở đường
Biết im lặng là tránh họa
Ở 1 mình là tu dưỡng
Đi qua đáy là tái sinh
Trải nghiệm nhiều là trưởng thành
Tâm vui vẻ là hạnh phúc

Đến khi mà bạn thực sự hiểu được những điều này... thì xin chúc mừng bạn đã tốt nghiệp "Trường đời" rồi.',
 'bai_mau', array['tam_linh','quan_diem','listicle']),
('CHỈ CẦN BẠN DÁM KẾT THÚC NGHIỆT DUYÊN THÌ LẬP TỨC CÓ THỂ ĐỔI MỆNH',
 'Chỉ cần bạn dám kết thúc nghiệt duyên thì lập tức có thể đổi mệnh. Nhưng kết thúc ở đây không chỉ là rời khỏi một người. Mà là thật sự học xong bài học mà mối quan hệ đó mang đến. Nếu cố chấp níu kéo, kết cục sẽ rất thảm.

Nghiệt duyên chính là nhân từ kiếp trước, chỉ cần bạn trả xong thì phải lập tức rời đi. Nếu không, từ trường không hợp, đối phương sẽ hút cạn vận khí của bạn.

Cái gọi là nghiệt duyên, thực ra đều là thứ đã có sẵn trong mệnh. Bạn muốn tránh cũng không tránh được. Một khi đã bị cuốn vào, bạn sẽ phải dây dưa lặp đi lặp lại với một người không có kết quả. Từ việc liên tục tự hao tổn bản thân, đến việc vì họ mà đánh mất nguyên tắc, cuối cùng bị dày vò đến mức chỉ còn nửa cái mạng.

Nhưng trong quá trình đó, thực chất là bạn đang vượt kiếp. Bởi nghiệp duyên không chỉ đến để làm bạn đau. Nghiệp duyên đến để dạy bạn một bài học mà có thể kiếp trước bạn chưa học xong, hoặc linh hồn bạn trong kiếp này cần phải đi qua để trưởng thành hơn.

Có những mối quan hệ xuất hiện không phải để ở lại, mà để soi cho bạn thấy: bạn còn thiếu điều gì, còn chấp vào điều gì, còn sợ mất điều gì, còn chưa biết yêu thương và bảo vệ chính mình ở đâu.

Chỉ khi bạn vượt qua được kiếp nạn này, bạn mới có thể thuận lợi bước vào vận tốt của cuộc đời. Phải hiểu rằng, con người thiếu cái gì thì càng dễ mê đắm cái đó. Vì vậy ông trời mới mượn đoạn nghiệt duyên này để hết lần này đến lần khác thử thách bạn.

Nếu bạn chỉ kết thúc một mối nghiệp duyên bằng sự oán trách, tổn thương và né tránh, nhưng không thật sự học được bài học bên trong nó, thì rất có thể sau đó bạn sẽ lại gặp một người khác, trong một hoàn cảnh khác, nhưng mang cùng một bài học cũ. Bởi vũ trụ không trừng phạt bạn. Vũ trụ chỉ lặp lại bài học cho đến khi bạn thật sự hiểu.

Vậy làm sao để phân biệt người trước mắt là nghiệt duyên hay chính duyên? Hãy xem người đó có nuôi dưỡng bạn hay không. Họ có khiến bạn trở nên từ bi hơn, có khơi dậy phần thiện trong bạn hay không? Nếu họ khiến bạn cảm thấy tương lai ngày càng tốt đẹp thì đó chính là chính duyên của bạn. Nhưng nếu họ khơi dậy phần xấu trong bạn, khiến bạn ngày nào cũng lo được lo mất, tính toán chi ly, thậm chí bắt đầu ghét chính mình, thì đó chính là nghiệt duyên.

Thông thường nợ tình chỉ cần ở bên nhau một năm là trả xong. Nếu dây dưa nhiều năm lặp đi lặp lại thì vận khí của bạn cũng đã bị hút gần cạn. Thực ra trước đó ông trời đã cho bạn rất nhiều cơ hội để rời đi, âm thầm đẩy bạn ra khỏi mối quan hệ này, nhưng bạn vì không cam lòng mà cố chấp chờ đợi. Cuối cùng mới rơi vào kết cục dang dở như vậy.

Vì thế nhất định phải thuận theo thiên mệnh. Duyên lành do trời định sẽ không khiến bạn phải vất vả cầu xin. Kết thúc một người chưa chắc đã là hết nghiệp. Hiểu được bài học phía sau người đó, mới là lúc bạn thật sự trả xong nghiệp.

Chúc bạn sớm gặp được chính duyên, hôn nhân hạnh phúc.',
 'bai_mau', array['tam_linh','hon_nhan','tinh_yeu']),
('BỐN BƯỚC TÍCH SẢN DÀNH CHO NGƯỜI ĐANG CÓ NỢ',
 'Nhiều người nghĩ: "Đang nợ thì lấy gì mà tích sản?" Nhưng thực tế người nợ nhiều nhất thường là người cần tích sản sớm nhất. Vì nếu chỉ chăm chăm trả nợ mà không xây tài sản, bạn sẽ rơi vào vòng lặp: trả xong — thở — rồi lại vay.

Mình từng ở trạng thái đó. Tập trung trả nợ cho nhẹ đầu, mà quên mất phải xây nền tài chính cho vững. Thế nên chỉ cần một biến động nhỏ là mọi thứ lại chao đảo. Vấn đề không nằm ở số nợ. Vấn đề nằm ở cấu trúc dòng tiền và tư duy tích sản.

1) ĐỪNG TRẢ NỢ BẰNG CẢM XÚC — TRẢ NỢ BẰNG CẤU TRÚC
Người có nợ thường có xu hướng: hoảng, muốn xoá sạch ngay, all-in toàn bộ tiền vào trả nợ. Nhưng nếu bạn trả hết tiền mặt mà không giữ quỹ chống sốc, chỉ cần 1 sự cố nhỏ, bạn lại phải vay. Trả nợ đúng là cần. Nhưng phải song song xây "quỹ chống rung". Nguyên tắc: không để tài khoản về 0 vì cảm giác tội lỗi.

2) XÂY 3 LỚP TIỀN SONG SONG
Trong giai đoạn có nợ, bạn vẫn cần: 1 lớp tiền chống sốc (3-6 tháng chi phí cơ bản), 1 lớp tiền tạo giá trị (đầu tư vào kỹ năng/thương hiệu cá nhân/sức khoẻ), 1 lớp tiền tích sản nhỏ nhưng đều (vàng, tài sản số, quỹ chỉ số...). Tích sản không bắt đầu bằng số lớn. Nó bắt đầu bằng thói quen giữ lại một phần nhỏ trước khi tiêu. Người nghèo thường đợi hết nợ mới tích sản. Người khôn bắt đầu tích sản ngay trong lúc còn nợ.

3) CHUYỂN NỢ XẤU THÀNH NỢ CÓ MỤC ĐÍCH
Không phải mọi khoản nợ đều xấu. Nợ tiêu dùng để chứng minh mình giàu → rò tài lộc. Nợ để mua tài sản sinh dòng tiền → chiến lược. Hãy phân loại: nợ làm mình yếu đi, hay nợ giúp mình mạnh hơn? Nếu đang có nợ tiêu dùng, mục tiêu là thu hẹp nhanh. Nếu là nợ đầu tư có dòng tiền, cần tối ưu hiệu suất.

4) TÍCH SẢN LỚN NHẤT LÀ NÂNG CẤP BẢN THÂN
Trong 1-3 năm đầu khi còn nợ, tài sản quan trọng nhất không phải vàng hay đất. Mà là năng lực kiếm tiền, năng lực quản lý tiền, sức khoẻ để hành động bền. Nếu gan yếu, năng lượng thấp, quyết định sẽ sai. Quyết định sai thì dòng tiền lệch. Tích sản không chỉ là giữ tiền. Mà là giữ được trạng thái đủ tỉnh để tiền ở lại.

Người có nợ không đáng sợ. Người không có cấu trúc mới đáng sợ. Nếu bạn đang có nợ nhưng không biết mỗi tháng tiền mình đang rò ở đâu, thì vấn đề không nằm ở thu nhập — mà nằm ở việc bạn chưa nhìn thấy dòng tiền thật của mình.

Khi dòng tiền rõ ràng, nợ không còn đáng sợ. Nếu hôm nay bạn đủ can đảm nhìn thẳng vào dòng tiền của mình, 5 năm nữa bạn sẽ cảm ơn bản thân vì đã dám lựa chọn để tiến lên.',
 'bai_mau', array['tai_chinh','tich_san','no']);

